import{_ as r,o as a,c as t,ae as o}from"./chunks/framework.Iv6F95cJ.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/algo-beauty/打卡召集令 - 60 天攻克数据结构与算法.md","filePath":"books/algo-beauty/打卡召集令 - 60 天攻克数据结构与算法.md"}'),p={name:"books/algo-beauty/打卡召集令 - 60 天攻克数据结构与算法.md"};function n(s,e,g,l,i,_){return a(),t("div",null,[...e[0]||(e[0]=[o('<p>你好，我是王争。</p><p>今年4月，专栏更新结束之后，我在专栏发布了一篇<a href="https://time.geekbang.org/column/article/91541" target="_blank" rel="noreferrer">《数据结构与算法之美》学习指导手册》</a>，在这篇文章里，我对专栏内容重新做了一次梳理，将整个专栏拆分成四个阶段，列出了每个阶段的核心知识点、标注了每个知识点的难易程度（E-Easy，M-Medium，H-Hard），并用 1-10 分说明其重要性。</p><p><img src="https://static001.geekbang.org/resource/image/3e/b7/3eb147a56e5b1452692fbbd4498075b7.png?wh=2048%2A1671" alt="unpreview" loading="lazy" referrerpolicy="no-referrer"></p><p>但是，我发现，很多同学还是没能坚持下来，久而久之对学习算法失去了信心。</p><p>回想起来，写专栏之初，我就立下 Flag，要做一个跟国内外经典书籍不一样、可以长期影响一些人的专栏。所以，在专栏完结 9 个月后，我想再做一些事情。</p><p>为了带你彻底拿下“数据结构与算法”这座大山，我发起了**“60 天攻克数据结构与算法”打卡行动**，一起登顶！</p><p>下面是我为你精心规划的学习计划表：</p><p><img src="https://static001.geekbang.org/resource/image/12/6e/12a5a67041dbd5c1e65d72f0fbe4c86e.jpg?wh=750%2A8106" alt="" loading="lazy" referrerpolicy="no-referrer"></p><p><strong>活动时间</strong>：2019.11.25-2020.1.19</p><p><strong>你将获得</strong>：<br> 1.坚持 60 天，与 2000 位优秀的工程师一起，彼此激励，相互学习；<br> 2.整个学习周期内，我会进行2次高质量的社群分享；<br> 3.我会精心整理 4 张知识脑图，为你梳理每个阶段的学习重点，发布在专栏里；<br> 4.我和极客时间准备了 20 万奖学金，给坚持下来的同学。</p><p><strong>活动规则</strong>：<br> 在下方申请进入活动打卡群，根据课表打卡，完成学习。</p><p><a href="https://jinshuju.net/f/DYtafE" target="_blank" rel="noreferrer"><img src="https://static001.geekbang.org/resource/image/f7/e6/f7f62d8fbf411f179cd16c914e0151e6.png?wh=750%2A166" alt="unpreview" loading="lazy" referrerpolicy="no-referrer"></a><br><strong>打卡要求</strong>：<br> 1.每个阶段持续 2 周，每周仅需打卡 3 次，即视为完成该阶段的学习。<br> 2.4个阶段（8 周）的学习，打卡总数仅需 30 次，即视为完成“60 天攻克数据结构与算法行动”。<br> 3.为了让大家养成习惯，每日只计 1 次打卡，单日内多次打卡视为 1 次。</p><p><strong>进入打卡群后，完成学习还有如下奖励</strong>：</p><ul><li>第一阶段（第1-2周）：¥15 奖励金</li><li>第二阶段（第3-4周）：¥25 奖励金</li><li>第三阶段（第5-6周）：¥35 奖励金</li><li>四个阶段（第7-8周）：¥50 奖励金</li></ul><p>（注：奖励金会以无门槛优惠券形式、分阶段进行发放，发放时间为每阶段结束后的 7 个工作日内。）</p><p>当然，优惠券只是对你的小小奖励。坚持 60 天，与 2000 位优秀的工程师一起，互相学习，彼此激励，彻底拿下数据结构与算法，我奉陪到底。</p><p><img src="https://static001.geekbang.org/resource/image/a6/88/a63516bc3b13ae1a18adcbb83c969888.png?wh=750%2A328" alt="unpreview" loading="lazy" referrerpolicy="no-referrer"> 精选留言（15） 传说中的成大大 👍（0） 💬（1）争哥 我一直在坚持 除了数据结构和算法外 连设计模式我也一直跟得很勤2019-11-22youyou.L 👍（12） 💬（0）我都快学完才发现这东西，放在开头多好啊2020-11-12Cy23 👍（8） 💬（0）加油，这次我一定跟着学完2019-11-22进德修业 👍（4） 💬（0）以终为始，从现在开始，刷三百九十九道leetcode算法题，先用java刷，后面复习用go刷，请大家监督@.@2023-07-02数字记忆 👍（4） 💬（1）零零散散学了两年了，还没学完2021-06-02小童 👍（2） 💬（0）好好学习2020-04-13谭方敏 👍（2） 💬（1）完美错过了2020-03-07吃草🐴~ 👍（2） 💬（0）🤔🤔 一起打卡学习~2019-11-22creasylai19 👍（1） 💬（0）我又重新来学算法啦2022-07-25Eternal 👍（1） 💬（0）害怕 担忧 犹豫 尝试各种方法 放弃 心里的坎过不去 找回初心 找资料 计划按照老师的计划表刷一遍，不偷懒，一点一点啃2021-08-21Donkey 👍（1） 💬（0）自律要成为一种习惯！2020-02-24Geek_6137ce 👍（0） 💬（0）打卡打卡2024-05-11just you 👍（0） 💬（0）老师，打扰一下。我这遇到个问题，一直没有思路，如果您看到，帮忙给指导一下 判断一个字符串中有多少种AAB类型的子串，比如“好好学习，好好学习，天天向上”中有两种AAB的句式，而不是三种。 此题解题逻辑说明，“好好学”是一种，“天天向”是一种，所以是两种，再比如“好好学学吧”可以看成“好好学”和“学学吧”，这种叠加情况要被排除，只认为是“好好学”这一种2022-01-15石天兰爱学习 👍（0） 💬（0）2021、11、09打卡学习2021-11-09蹲街丶惜流年 👍（0） 💬（0）看第四次了，很感谢作者的分享。2021-09-29</p>',17)])])}const f=r(p,[["render",n]]);export{b as __pageData,f as default};
